package main

import (
	_ "embed"
	"net/http"
)

// openapiDoc is the committed OpenAPI 3.1 document — cmd/sandbin/openapi.json, generated by
// `make openapi` and corrected by cmd/sandbin/openapi-fix.jq (docs/decisions/0030-api-servemux-openapi.md).
// Embedding it makes GET /openapi.json answer byte for byte the file the contract tests read;
// the file already carries its trailing newline, so the handler adds none.
//
//go:embed openapi.json
var openapiDoc []byte

// serveOpenAPI answers GET /openapi.json: the machine-readable contract, served verbatim
// from the embedded file. It needs no key, touches no store and charges nothing, so it
// answers even while its address is blocked. Every other method is refused by the route
// table before this handler is reached, and the one path the table names is spelled exactly
// — a trailing slash names no entry and stays the plain 404.
func (s *server) serveOpenAPI(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Write(openapiDoc)
}
